const ctx = $json;
const escMd = (v) => String(v ?? '').replace(/([\\_*`\[])/g, '\\$1');
const esRevision = ctx.estado === 'revision_manual';
const tieneFoto = Boolean(ctx.foto_file_id && String(ctx.foto_file_id).trim());

const ex = ctx.extraccion && typeof ctx.extraccion === 'object' ? ctx.extraccion : {};
const val = ctx.validacion && typeof ctx.validacion === 'object' ? ctx.validacion : {};

const estudiante = ctx.estudiante_nombre
  ? `${escMd(ctx.estudiante_nombre)}${ctx.estudiante_codigo ? ` (${escMd(ctx.estudiante_codigo)})` : ''}`
  : (ctx.estudiante_codigo ? escMd(ctx.estudiante_codigo) : 'No identificado');

const curso = ctx.curso
  ? `${escMd(ctx.curso)}${ctx.paralelo ? ` ${escMd(ctx.paralelo)}` : ''}`
  : 'No identificado';

const fechasLista = Array.isArray(val.fechas) && val.fechas.length
  ? val.fechas
  : (Array.isArray(val.fechas_pedidas) && val.fechas_pedidas.length
    ? val.fechas_pedidas
    : (Array.isArray(ex.fechas) ? ex.fechas : []));
const fechasTexto = fechasLista.length ? fechasLista.map(escMd).join(', ') : 'Sin fechas';

const motivosTexto = {
  salud: 'Salud',
  calamidad_domestica: 'Calamidad doméstica',
  transporte: 'Transporte',
  tramite: 'Trámite',
  otro: 'Otro',
};
const motivoClave = typeof ex.motivo === 'string' ? ex.motivo : '';
const motivoNombre = motivosTexto[motivoClave] ?? (motivoClave ? escMd(motivoClave) : 'Sin especificar');
const resumen = typeof ex.resumen === 'string' && ex.resumen.trim()
  ? escMd(ex.resumen.trim())
  : (typeof ctx.mensaje_original === 'string' && ctx.mensaje_original.trim()
    ? escMd(ctx.mensaje_original.trim().slice(0, 200))
    : 'Sin detalle');

const reglas = Array.isArray(val.reglas)
  ? val.reglas.filter((r) => r && typeof r === 'object' && !Array.isArray(r))
  : [];
const reglasLineas = reglas.length
  ? reglas.map((r) => `${r.ok ? '✅' : '❌'} ${escMd(r.id)}: ${escMd(r.detalle ?? '')}`)
  : ['ℹ️ Sin detalle de reglas'];

const cabecera = esRevision
  ? `⚠️ *REVISIÓN MANUAL* · Justificativo #${escMd(ctx.id ?? '')}`
  : `📋 *Justificativo #${escMd(ctx.id ?? '')}*`;

const lineas = [
  cabecera,
  `👤 Estudiante: ${estudiante}`,
  `🏫 Curso: ${curso}`,
  `📅 Fechas: ${fechasTexto}`,
  `📝 Motivo: ${motivoNombre} — ${resumen}`,
  `📎 Foto adjunta: ${tieneFoto ? 'Sí' : 'No'}`,
  '',
  'Reglas C6:',
  ...reglasLineas,
];

return {
  json: {
    id: ctx.id ?? null,
    estado: ctx.estado ?? null,
    es_revision_manual: esRevision,
    inspector_chat_id: ctx.inspector_chat_id ?? null,
    foto_file_id: tieneFoto ? String(ctx.foto_file_id).trim() : null,
    tiene_foto: tieneFoto,
    mensaje: lineas.join('\n'),
  },
};

const dias = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
  'septiembre', 'octubre', 'noviembre', 'diciembre'];

function fechaEnPalabras(fecha) {
  const dia = new Date(String(fecha).slice(0, 10) + 'T00:00:00Z');
  if (Number.isNaN(dia.getTime())) return String(fecha);
  return `el ${dias[dia.getUTCDay()]} ${dia.getUTCDate()} de ${meses[dia.getUTCMonth()]}`;
}

function conFechas(fechas, redactar, maximo = 300) {
  const enPalabras = fechas.map(fechaEnPalabras);
  const lista = [enPalabras.slice(0, -1).join(', '), enPalabras.at(-1)].filter(Boolean).join(' y ');
  const mensaje = redactar(lista);
  if (mensaje.length <= maximo || fechas.length < 2) return mensaje;
  return redactar(`${enPalabras[0]} y ${fechas.length - 1} más`);
}

const { decision, telegram_chat_id, estudiante_nombre, fechas } = $json;
const chatId = telegram_chat_id ? String(telegram_chat_id).trim() : null;

if (decision === 'aprobado') {
  return {
    json: {
      telegram_chat_id: chatId,
      decision,
      mensaje: 'Tu justificativo fue aprobado',
    },
  };
}

const nombre = typeof estudiante_nombre === 'string' && estudiante_nombre.trim()
  ? estudiante_nombre.trim().split(/\s+/)[0].slice(0, 40)
  : '';
const fechasValidas = Array.isArray(fechas)
  ? fechas.filter((f) => typeof f === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(f))
  : [];
const ayuda = 'Si necesitas ayuda, inspección te atiende con gusto en el colegio.';

let mensaje;
if (fechasValidas.length) {
  const sujeto = nombre ? `el justificativo de ${nombre}` : 'tu justificativo';
  mensaje = conFechas(fechasValidas, (lista) =>
    `Hola 🙏 Inspección revisó ${sujeto} para ${lista}, pero no pudo aprobarlo esta vez. ${ayuda}`);
} else if (nombre) {
  mensaje = `Hola 🙏 Inspección revisó el justificativo de ${nombre}, pero no pudo aprobarlo esta vez. ${ayuda}`;
} else {
  mensaje = `Hola 🙏 Inspección revisó tu justificativo, pero no pudo aprobarlo esta vez. ${ayuda}`;
}

return {
  json: {
    telegram_chat_id: chatId,
    decision,
    mensaje: mensaje.slice(0, 300),
  },
};
